fn ar68_f3_appended_permissive_rule_is_refused_reported_and_without_effect() {
    let archive_kernel = path_rule(
        "archive/**",
        json!({"class": "historical", "default_retrieval": false, "mutation": "restricted",
               "semantic_index": false, "lexical_index": true, "graph_index": false, "namespace": "archive"}),
    );
    let kernel = json!([archive_kernel.clone()]);
    let widening = path_rule(
        "archive/*.txt",
        json!({"class": "source", "mutation": "allowed", "agent_read": "allowed", "export": "allowed",
               "sensitivity": "public", "semantic_index": true, "lexical_index": true, "graph_index": true,
               "code_index": true, "namespace": "product"}),
    );
    let new_value = json!([archive_kernel.clone(), widening.clone()]);
    let v = evaluate_path_rules_overlay(
        Some(&kernel),
        &new_value,
        "REPOSITORY_CONTRACT",
        "REPOSITORY_CONTRACT.yaml",
    );
    // reported: policy, key, value, kernel_value, reason
    let hit = v
        .refused
        .iter()
        .find(|r| r["value"]["pattern"] == "archive/*.txt")
        .unwrap_or_else(|| panic!("no refusal for archive/*.txt: {:?}", v.refused));
    assert_eq!(hit["policy"], "REPOSITORY_CONTRACT");
    assert_eq!(hit["key"], "paths");
    assert_eq!(hit["value"]["mutation"], "allowed");
    assert_eq!(hit["kernel_value"]["pattern"], "archive/**");
    let reason = hit["reason"].as_str().unwrap();
    assert!(reason.contains("widen"), "{reason}");
    assert!(reason.contains("archive/**"), "{reason}");
    // the mutation dimension itself must be the one caught (not merely some other field that happens to
    // also differ) -- pins the AR68-F3 witness-construction bug this test would otherwise mask.
    assert!(reason.contains("mutation"), "{reason}");
    // without effect: the widening rule never reaches the effective document
    let effective = v.effective.as_array().unwrap();
    assert!(
        !effective.iter().any(|r| r["pattern"] == "archive/*.txt"),
        "{effective:?}"
    );
    let contract = crate::paths::RepositoryContract::new(json!({"paths": effective}));
    let d = contract.decide("archive/a.txt");
    assert_eq!(d.str("mutation"), "restricted", "kernel floor still decides");
    let d2 = contract.decide("archive/b.txt");
    assert_eq!(d2.str("mutation"), "restricted");

    // the sibling validator (`evaluate()`'s "path_rules" mode) refuses the same edit
    let err = evaluate_path_rules(Some(&kernel), &new_value).unwrap_err();
    assert!(err.contains("widen"), "{err}");
}

